settings.air_reviews_json_ld_v2:
{% assign productTitle = product.title | default: '' %}{% assign productDesc = product.description | strip_html | default: '' | truncate: 150 %}{% assign productImage = product.featured_image | default: '' %}{% assign productUrl = product.url | prepend: request.origin %}{% assign ratingValue = product.metafields.reviews.rating.value.rating | default: product.metafields.air_reviews_product.review_avg | default: 0 %}{% assign bestRating = product.metafields.reviews.rating.value.scale_max | default: 5 %}{% assign reviewCount = product.metafields.air_reviews_product.review_count | default: 0 %}{% assign worstRating = product.metafields.reviews.rating.value.scale_min | default: 1 %}{
"@context": "http://schema.org",
"@type": "Product",
"@id": {{ productUrl | append: '#product' | json }},
"url": {{ productUrl | json }},
"name": {{ productTitle | json }},
"description": {{ productDesc | json }},
"image": {{ productImage | json }},
"aggregateRating": {
  "@type": "AggregateRating",
  "ratingValue": {{ ratingValue }},
  "bestRating": {{ bestRating }},
  "reviewCount": {{ reviewCount }}
 }{% if shop.metafields.air_reviews_has_ugc_content.data.value == true and product.metafields.air_reviews_product.data.value.reviews %}, 
  "review":[{% assign reviewsData = product.metafields.air_reviews_product.data.value.reviews %}
  {% for review in reviewsData limit: 10 %}
    {
      "@type": "Review",
      "author": {
        "@type": "Person",
        "name": {% if review.firstName %}{{ review.firstName | json }}{% elsif review.lastName %}{{ review.lastName | json }}{% else %}{{ 'Anonymous' | json }}{% endif %}
      },
      "reviewRating": {
          "@type": "Rating",
          "bestRating": {{ bestRating }},
          "ratingValue": {{ review.rate | default: 0 }},
          "worstRating": {{ worstRating }}
      },
      "reviewBody": {{ review.content | strip_html | default: '' | json }},
      "datePublished": {{ review.createdAt | date: '%Y-%m-%d' | json }}
    }{% unless forloop.last %},{% endunless %} 
  {% endfor %}]{% endif %}
}
